# Analysis is fused into SmaCombined below -- composeSavedStrategyCerebro
# only wires bt.Strategy hooks for the entry wrapper, so a separate analysis
# Strategy could not share state with entry/exit. TICKET_794 Phase 2 finding:
# the Python composition model needs a single combined bt.Strategy. This
# component is kept for compose-script schema parity but emits no code.
class SmaAnalysis(bt.Strategy):
    def __init__(self, state_manager=None):
        self.state_manager = state_manager
    def next(self):
        pass

class SmaCombined(bt.Strategy):
    # Combined analysis + entry + exit so position state is shared. Mirrors
    # the C++ composer's ComposedLiveStrategy semantics (analysis populates
    # ctx, entry edge-fires, exit closes after hold_bars).
    params = (('period', 20), ('hold_bars', 5))

    def __init__(self, state_manager=None):
        self.state_manager = state_manager
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.params.period)
        self.order = None
        self.prev_above = False
        self.entry_bar = None

    def next(self):
        if len(self.sma) < self.params.period:
            return
        above = self.data.close[0] > self.sma[0]
        if self.order is not None:
            self.prev_above = above
            return
        if not self.position:
            if above and not self.prev_above:
                self.order = self.buy(size=1)
        else:
            if self.entry_bar is not None and (len(self) - self.entry_bar) >= self.params.hold_bars:
                self.order = self.sell(size=self.position.size)
        self.prev_above = above

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.entry_bar = len(self)
            else:
                self.entry_bar = None
            self.order = None
        elif order.status in (order.Canceled, order.Rejected, order.Margin):
            self.order = None

# Exit logic is fused into SmaCombined above for the reason explained on
# SmaAnalysis. This stub exists so the composer schema (3 components) is
# satisfied and exercises composeSavedStrategyCerebro's exit-branch code.
class NBarExit(bt.Strategy):
    def __init__(self, state_manager=None):
        self.state_manager = state_manager
    def next(self):
        pass
